def _raw_patch_values(root, patch, time):
    """regionCoupledOFFBEAT 元数据缺失时，用原生字典读取存储的面值。"""
    entry = f'boundaryField/{patch}/value'
    out = subprocess.run(
        ['foamDictionary', f'./{time}/T', '-disableFunctionEntries', '-no-libs',
         '-noFunctionObjects', '-entry', entry, '-value'],
        cwd=root, capture_output=True, text=True)
    if out.returncode != 0:
        raise RuntimeError(f'foamDictionary 读取 {patch} 失败: {out.stderr.strip()}')
    text = out.stdout
    if 'nonuniform' in text:
        body = text.split('(', 1)[1].rsplit(')', 1)[0]
        values = [float(v) for v in re.findall(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', body)]
    else:
        values = [float(re.findall(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', text)[-1])]
    return values


def _patch_stats(root, patch, time, owner_zone=None):
    try:
        frame = result_api.read_field(root, 'T', time=time, scope=('patch', patch),
                                     owner_zone=owner_zone)
        values = [float(v) for v in frame.values]
        source = 'result_api'
    except Exception:
        values = _raw_patch_values(root, patch, time)
        source = 'foamDictionary(boundaryField/<patch>/value)'
    return {'n_faces': len(values), 'source': source,
            'mean_K': sum(values) / len(values),
            'min_K': min(values), 'max_K': max(values)}

