def patch_value(name, patch, t=30000):
    text = open(os.path.join(CASE, str(t), name), "r", errors="ignore").read()
    idx = text.find("boundaryField")
    if idx < 0:
        return None
    sub = text[idx:]
    m = re.search(r"\b" + patch + r"\s*\{(.*?)\}", sub, re.S)
    if not m:
        return None
    v = re.search(r"value\s+uniform\s+([-+0-9.eE]+)", m.group(1))
    return float(v.group(1)) if v else None


